from bookings import Booking
from settle import is_settled


def test_tenths():
    assert is_settled([Booking("a", 0.1), Booking("b", 0.2)], 0.3)


def test_three_tenths():
    assert is_settled([Booking("a", 0.1), Booking("b", 0.1), Booking("c", 0.1)], 0.3)


def test_not_settled():
    assert not is_settled([Booking("a", 0.1), Booking("b", 0.2)], 0.31)


def test_whole_numbers():
    assert is_settled([Booking("a", 2), Booking("b", 3)], 5) and not is_settled([Booking("a", 2), Booking("b", 3)], 6)


def test_nothing_owed():
    assert is_settled([], 0)

